    public function has(string $name): bool
    {
        return isset(self::ICONS[$name]);
    }

    public function render(string $name, string $class = '', ?string $label = null): string
    {
        $paths = self::ICONS[$name] ?? self::ICONS['info'];
        $filled = \in_array($name, self::FILLED, true);
        $a11y = null !== $label
            ? 'role="img" aria-label="'.htmlspecialchars($label, \ENT_QUOTES | \ENT_HTML5, 'UTF-8').'"'
            : 'aria-hidden="true" focusable="false"';

        return \sprintf(
            '<svg class="icon icon-%s %s" viewBox="0 0 24 24" width="24" height="24" %s %s>%s</svg>',
            htmlspecialchars($name, \ENT_QUOTES),
            htmlspecialchars($class, \ENT_QUOTES),
            $filled ? 'fill="currentColor" stroke="none"' : 'fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"',
            $a11y,
            $paths,
        );
    }
}
